function assembleDeploymentRegistry(locations, units) {
  if (!Array.isArray(locations) || !Array.isArray(units)) throw new TypeError('Inputs must be arrays');
  const locationCodes = new Set();
  const builtLocations = locations.map((location, index) => {
    if (!location || typeof location !== 'object' ||
        !['code', 'label', 'category'].every((key) => typeof location[key] === 'string' && location[key].length > 0) ||
        !Number.isFinite(location.latitude) || !Number.isFinite(location.longitude)) {
      throw new TypeError('Invalid location');
    }
    if (locationCodes.has(location.code)) throw new RangeError('Duplicate location code');
    locationCodes.add(location.code);
    return { ...location, id: 100 + index };
  });
  const byCode = new Map(builtLocations.map((location) => [location.code, location]));
  const serials = new Set();
  const builtUnits = units.map((unit) => {
    if (!unit || typeof unit !== 'object' ||
        !['serial', 'locationCode', 'contact'].every((key) => typeof unit[key] === 'string' && unit[key].length > 0)) {
      throw new TypeError('Invalid unit');
    }
    if (serials.has(unit.serial)) throw new RangeError('Duplicate unit serial');
    serials.add(unit.serial);
    const location = byCode.get(unit.locationCode);
    if (!location) throw new RangeError('Unknown location code');
    return { serial: unit.serial, locationId: location.id + 1, contact: unit.contact };
  });
  return Promise.resolve({ locations: builtLocations, units: builtUnits });
}

module.exports = { assembleDeploymentRegistry };

