'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['assembleDeploymentRegistry']);
const { assembleDeploymentRegistry } = api;

(async () => {
  const locations = [
    { code: 'BLR', label: 'Bengaluru', category: 'hub', latitude: 12.9, longitude: 77.6 },
    { code: 'DEL', label: 'Delhi', category: 'edge', latitude: 28.6, longitude: 77.2 }
  ];
  const units = [
    { serial: 'u2', locationCode: 'DEL', contact: 'del@example.test' },
    { serial: 'u1', locationCode: 'BLR', contact: 'blr@example.test' }
  ];
  const locationsSnapshot = locations.map((value) => ({ ...value }));
  const unitsSnapshot = units.map((value) => ({ ...value }));
  const pending = assembleDeploymentRegistry(locations, units);
  assert.ok(pending && typeof pending.then === 'function');
  locations[0].label = 'mutated';
  units[0].contact = 'mutated';
  const registry = await pending;
  assert.deepStrictEqual(registry, {
    locations: [
      { code: 'BLR', label: 'Bengaluru', category: 'hub', latitude: 12.9, longitude: 77.6, id: 100 },
      { code: 'DEL', label: 'Delhi', category: 'edge', latitude: 28.6, longitude: 77.2, id: 101 }
    ],
    units: [
      { serial: 'u2', locationId: 101, contact: 'del@example.test' },
      { serial: 'u1', locationId: 100, contact: 'blr@example.test' }
    ]
  });
  assert.deepStrictEqual(locationsSnapshot[0].label, 'Bengaluru');
  assert.deepStrictEqual(unitsSnapshot[0].contact, 'del@example.test');
  assert.notStrictEqual(registry.locations[0], locations[0]);
  assert.notStrictEqual(registry.units[0], units[0]);
  registry.locations[0].label = 'returned mutation';
  assert.strictEqual(locationsSnapshot[0].label, 'Bengaluru');
  assert.deepStrictEqual(await assembleDeploymentRegistry([], []), { locations: [], units: [] });

  const rejects = async (locationsArg, unitsArg, ErrorType) => {
    await assert.rejects(async () => assembleDeploymentRegistry(locationsArg, unitsArg), ErrorType);
  };
  await rejects(null, [], TypeError);
  await rejects([], {}, TypeError);
  await rejects([{ code: '', label: 'x', category: 'x', latitude: 0, longitude: 0 }], [], TypeError);
  await rejects([{ code: 'x', label: 'x', category: 'x', latitude: Infinity, longitude: 0 }], [], TypeError);
  await rejects([{ code: 'x', label: 'x', category: 'x', latitude: '0', longitude: 0 }], [], TypeError);
  await rejects([{ code: 'x', label: 'x', category: 'x', latitude: 0, longitude: 0 }], [
    { serial: '', locationCode: 'x', contact: 'c' }
  ], TypeError);
  await rejects([
    { code: 'x', label: 'one', category: 'a', latitude: 0, longitude: 0 },
    { code: 'x', label: 'two', category: 'b', latitude: 1, longitude: 1 }
  ], [], RangeError);
  await rejects([{ code: 'x', label: 'x', category: 'x', latitude: 0, longitude: 0 }], [
    { serial: 'same', locationCode: 'x', contact: 'a' },
    { serial: 'same', locationCode: 'x', contact: 'b' }
  ], RangeError);
  await rejects([{ code: 'x', label: 'x', category: 'x', latitude: 0, longitude: 0 }], [
    { serial: 'u', locationCode: 'missing', contact: 'c' }
  ], RangeError);
})().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

